[metadata] {"type": "create", "filePath": "/workspace/repo/src/integrations/prefect-kubernetes/prefect_kubernetes/diagnostics.py", "content": """"Structured diagnosis of Kubernetes pod failures.

This module inspects a Kubernetes pod ``status`` dictionary and translates known
failure conditions (image pull errors, out-of-memory kills, crash loops,
scheduling failures, evictions, ...) into a structured
:class:`InfrastructureDiagnosis` that can be surfaced to users.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any


class DiagnosisLevel(str, Enum):
    """Severity level for an infrastructure diagnosis."""

    ERROR = "error"
    WARNING = "warning"


@dataclass(frozen=True)
class InfrastructureDiagnosis:
    """A structured diagnosis of a Kubernetes pod failure.

    The dataclass is frozen so instances are immutable and hashable, and two
    instances with identical field values compare as equal.
    """

    level: DiagnosisLevel
    summary: str
    detail: str
    resolution: str


def _iter_container_statuses(status: dict[str, Any]) -> list[dict[str, Any]]:
    """Return init container statuses followed by regular container statuses."""
    containers: list[dict[str, Any]] = []
    for key in ("initContainerStatuses", "containerStatuses"):
        value = status.get(key)
        if value:
            containers.extend(value)
    return containers


def diagnose_k8s_pod(status: dict[str, Any]) -> InfrastructureDiagnosis | None:
    """Inspect a pod status dictionary and return a structured diagnosis.

    Args:
        status: The ``status`` section of a Kubernetes pod object.

    Returns:
        An :class:`InfrastructureDiagnosis` describing a known failure
        condition, or ``None`` if the pod is healthy or in a state that does not
        require intervention.
    """
    if not status:
        return None

    containers = _iter_container_statuses(status)

    # Waiting-state failures take priority over terminated-state failures so
    # that, for a multi-container pod, an image pull error or crash loop is
    # reported before an out-of-memory kill.
    for container in containers:
        name = container.get("name", "")
        waiting = container.get("state", {}).get("waiting", {}) or {}
        reason = waiting.get("reason")
        message = waiting.get("message")

        if reason in ("ImagePullBackOff", "ErrImagePull"):
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=(
                    f"Container '{name}' could not pull its image ({reason})."
                ),
                detail=message or reason,
                resolution=(
                    "Verify the image name and tag are correct, the image "
                    "exists in the registry, and that valid image pull "
                    "credentials are configured."
                ),
            )

        if reason == "CrashLoopBackOff":
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=(
                    f"Container '{name}' is crash-looping (CrashLoopBackOff)."
                ),
                detail=message or reason,
                resolution=(
                    "Inspect the container logs to determine why the process "
                    "keeps exiting and address the underlying error."
                ),
            )

    # Terminated-state failures.
    for container in containers:
        name = container.get("name", "")
        terminated = container.get("state", {}).get("terminated", {}) or {}
        reason = terminated.get("reason")
        message = terminated.get("message")

        if reason == "OOMKilled":
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=(
                    f"Container '{name}' was terminated with OOMKilled "
                    "(ran out of memory)."
                ),
                detail=message or reason,
                resolution=(
                    "Increase the container's memory request and limit, or "
                    "reduce the amount of memory the workload uses."
                ),
            )

        if reason == "Evicted":
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.WARNING,
                summary=f"Container '{name}' was evicted from its node.",
                detail=message or reason,
                resolution=(
                    "Check node resource pressure and pod resource requests; "
                    "the pod may need to be rescheduled onto a node with more "
                    "available resources."
                ),
            )

    # Pod-level eviction (e.g. node-pressure eviction sets a pod-level reason).
    if status.get("reason") == "Evicted":
        message = status.get("message")
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.WARNING,
            summary="The pod was evicted from its node.",
            detail=message or "Evicted",
            resolution=(
                "Check node resource pressure and pod resource requests; the "
                "pod may need to be rescheduled onto a node with more "
                "available resources."
            ),
        )

    # Scheduling failures reported via the PodScheduled condition.
    for condition in status.get("conditions", []) or []:
        if (
            condition.get("type") == "PodScheduled"
            and condition.get("reason") == "Unschedulable"
        ):
            message = condition.get("message")
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.WARNING,
                summary="The pod is unschedulable and cannot be placed on a node.",
                detail=message or "Unschedulable",
                resolution=(
                    "Review the scheduling constraints, node availability, and "
                    "resource requests; the cluster may not have a node that "
                    "satisfies the pod's requirements."
                ),
            )

    return None
